    observed.remember_identity({"pid": 780302, "identity": {"pid": 780302, "start": [2, 0]},
                                "identity_error": None, "observed_by_epoch": 99.0})
    X.bsd_identity = lambda pid: ({"pid": pid, "start": [pid, 0]}, None)
    X.task_rss = lambda pid: 0
